use std::collections::HashMap;

pub fn anota(idades: &mut HashMap<String, i32>, nome: String, idade: i32) {
    idades.insert(nome, idade);
}

testsCode:
use desafio::anota;
use std::collections::HashMap;

#[test]
fn testa_a_idade_da_ana() {
    let mut idades = HashMap::new();
    anota(&mut idades, String::from("ana"), 9);
    assert_eq!(idades["ana"], 9);
}

#[test]
fn testa_o_valor_trocado() {
    let mut idades = HashMap::new();
    anota(&mut idades, String::from("bo"), 4);
    anota(&mut idades, String::from("bo"), 5);
    assert_eq!(idades["bo"], 5);
}
